const me = $('Instagram Hesabı Doğrula').first()?.json || {};
const igUserId = String(me.user_id || me.id || '').trim();
if (!igUserId) {
  throw new Error('Instagram hesabı doğrulanamadı. Token veya hesap türünü kontrol edin.');
}

const recentRaw = $('Son Paylaşımları Çek').first()?.json || {};
const recentPosts = Array.isArray(recentRaw.data) ? recentRaw.data : [];

const ghRaw = $input.first()?.json || {};
let posts = [];
try {
  const parsed = typeof ghRaw === 'string' ? JSON.parse(ghRaw) : (typeof ghRaw.data === 'string' ? JSON.parse(ghRaw.data) : ghRaw);
  if (Array.isArray(parsed.posts)) posts = parsed.posts;
} catch {}

if (posts.length === 0) return [];

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const readDiskPlatform = () => {
  try {
    const fs = require('fs');
    if (!fs.existsSync(GROWTH_PATH)) return {};
    const full = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8'));
    return (full && typeof full.instagram === 'object' && full.instagram) ? full.instagram : {};
  } catch { return {}; }
};
const sd = $getWorkflowStaticData('global');
const diskIg = readDiskPlatform();
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (Array.isArray(diskIg.sentIds)) sd.sentIds = [...new Set([...sd.sentIds, ...diskIg.sentIds])];
if (!Array.isArray(sd.sentHistory)) sd.sentHistory = [];
if (Array.isArray(diskIg.sentHistory)) {
  const seenH = new Set(sd.sentHistory.map((h) => h.postId + ':' + h.sentAt));
  for (const h of diskIg.sentHistory) { const k = h.postId + ':' + h.sentAt; if (!seenH.has(k)) { seenH.add(k); sd.sentHistory.push(h); } }
  sd.sentHistory = sd.sentHistory.slice(-50);
}
sd.lastPublishedAt = Math.max(Number(sd.lastPublishedAt || 0), Number(diskIg.lastPublishedAt || 0));

const nowSec = Math.floor(Date.now() / 1000);
const trtNow = new Date((nowSec + 3 * 3600) * 1000);
const todayTrt = trtNow.toISOString().slice(0, 10);
const hourTrt = trtNow.getUTCHours();

let execMode = 'trigger';
try { if (typeof $execution !== 'undefined' && $execution.mode) execMode = String($execution.mode); } catch {}
try { if (typeof $('Manuel Tetikle') !== 'undefined' && $('Manuel Tetikle').isExecuted) execMode = 'manual'; } catch {}
const isManual = execMode === 'manual';

let latestLiveTs = 0;
let liveTodayCount = 0;
let latestTodayMediaType = '';
const liveCaptions = [];
for (const m of recentPosts) {
  if (m.caption) liveCaptions.push(String(m.caption).toLowerCase().trim());
  if (m.timestamp) {
    const ts = Math.floor(Date.parse(m.timestamp) / 1000);
    if (Number.isFinite(ts) && ts > 0) {
      const dStr = new Date((ts + 3 * 3600) * 1000).toISOString().slice(0, 10);
      if (dStr === todayTrt) {
        liveTodayCount += 1;
        if (ts >= latestLiveTs) latestTodayMediaType = String(m.media_type || '').toUpperCase();
      }
      if (ts > latestLiveTs) latestLiveTs = ts;
    }
  }
}

const sdCountToday = sd.dayTrt === todayTrt ? Number(sd.countToday || 0) : 0;
const diskCountToday = diskIg.dayTrt === todayTrt ? Number(diskIg.countToday || 0) : 0;
sd.dayTrt = todayTrt;
sd.countToday = Math.max(liveTodayCount, sdCountToday, diskCountToday);
if (!isManual) {
  if (hourTrt < 15 || hourTrt > 23) return [];
  const effectiveLast = Math.max(sd.lastPublishedAt, latestLiveTs);
  if (sd.countToday >= 2) return [];
  if (effectiveLast && (nowSec - effectiveLast < 5 * 3600)) return [];
  const dayNum = Number(todayTrt.replace(/-/g, ''));

}

const sentSet = new Set(sd.sentIds);
const eligible = posts.filter((p) => {
  if (!p || !p.id || !p.caption) return false;
  if (sentSet.has(p.id)) return false;
  const mt = String(p.media_type || 'IMAGE').toUpperCase();
  if (mt === 'REELS') {
    if (!/^https:\/\//i.test(p.video_url || '') || !/\.mp4(?:\?|$)/i.test(p.video_url || '')) return false;
  } else if (mt === 'CAROUSEL') {
    if (!Array.isArray(p.slides) || p.slides.length < 2) return false;
    if (!p.slides.every((u) => /^https:\/\//i.test(u) && /\.jpe?g(?:\?|$)/i.test(u))) return false;
  } else {
    if (!/^https:\/\//i.test(p.image_url || '') || !/\.jpe?g(?:\?|$)/i.test(p.image_url || '')) return false;
  }
  const firstLine = String(p.caption).split('\n')[0].toLowerCase().trim();
  if (firstLine.length >= 20 && liveCaptions.some((c) => c.includes(firstLine))) return false;
  return true;
});

let candidate = null;
if (liveTodayCount === 1 && (latestTodayMediaType === 'REELS' || latestTodayMediaType === 'VIDEO')) {
  candidate = eligible.find((p) => String(p.media_type || '').toUpperCase() === 'CAROUSEL')
    || eligible.find((p) => String(p.media_type || 'IMAGE').toUpperCase() !== 'REELS')
    || eligible[0];
} else if (liveTodayCount === 0) {
  candidate = eligible.find((p) => String(p.media_type || '').toUpperCase() === 'REELS') || eligible[0];
} else {
  candidate = eligible[0];
}

if (!candidate) return [];

const mediaType = String(candidate.media_type || 'IMAGE').toUpperCase();
const coverUrl = mediaType === 'REELS'
  ? (candidate.cover_url || candidate.video_url.replace(/\.mp4(?:\?.*)?$/i, '_cover.jpg'))
  : null;

return [{
  json: {
    igUserId,
    username: String(me.username || 'socialora1'),
    postId: candidate.id,
    mediaType,
    videoUrl: candidate.video_url || null,
    coverUrl,
    slides: Array.isArray(candidate.slides) ? candidate.slides : null,
    imageUrl: candidate.image_url || null,
    caption: candidate.caption,
    nowSec,
    altText: String(candidate.title || 'Socialora creator tip').slice(0, 180),
    pollAttempt: 0
  }
}];

const res = $input.first()?.json || {};
const code = String(res.status_code || '').toUpperCase();
if (code === 'ERROR' || code === 'EXPIRED') {
  throw new Error('Instagram Reels konteyner hatası: ' + JSON.stringify(res));
}
const sd = $getWorkflowStaticData('global');
const creationId = String(res.id || $('Reels Konteyneri Oluştur').first().json.id);
const key = 'poll_' + creationId;
sd[key] = Number(sd[key] || 0) + 1;
const ready = code === 'FINISHED';
if (ready || sd[key] >= 6) {
  delete sd[key];
}
return [{ json: { id: creationId, status_code: code, ready, attempt: sd[key] || 6 } }];

const picked = $('İçerik Seç & Tekrar Kontrolü').first().json;
return (picked.slides || []).map((slideUrl) => ({
  json: {
    igUserId: picked.igUserId,
    slideUrl,
    caption: picked.caption,
    altText: picked.altText
  }
}));

const picked = $('İçerik Seç & Tekrar Kontrolü').first().json;
const children = $input.all().map((item) => item.json?.id).filter(Boolean);
if (children.length < 2) {
  throw new Error('Carousel çocuk konteynerleri oluşturulamadı.');
}
return [{ json: { igUserId: picked.igUserId, children, caption: picked.caption } }];

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const syncDiskPlatform = (patch, incrementCount) => {
  const fs = require('fs');
  const path = require('path');
  let full = {};
  try {
    if (fs.existsSync(GROWTH_PATH)) full = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) || {};
  } catch { full = {}; }
  const prev = (full && typeof full.instagram === 'object' && full.instagram) ? full.instagram : {};
  const mergedIds = [...new Set([...(Array.isArray(prev.sentIds) ? prev.sentIds : []), ...(Array.isArray(patch.sentIds) ? patch.sentIds : [])])];
  const prevDiskCount = prev.dayTrt === patch.dayTrt ? Number(prev.countToday || 0) : 0;
  const baseCount = Math.max(prevDiskCount, Number(patch.prevSdCount || 0));
  const nextCount = incrementCount ? baseCount + 1 : Math.max(baseCount, Number(patch.countToday || 0));
  const nextObj = {
    ...prev,
    ...patch,
    sentIds: mergedIds.slice(-300),
    lastPublishedAt: Math.max(Number(prev.lastPublishedAt || 0), Number(patch.lastPublishedAt || 0)),
    countToday: nextCount,
  };
  delete nextObj.prevSdCount;
  if (Array.isArray(patch.sentHistory)) {
    const prevH = Array.isArray(prev.sentHistory) ? prev.sentHistory : [];
    const seenH = new Set(prevH.map((h) => h.postId + ':' + h.sentAt));
    const combined = [...prevH];
    for (const h of patch.sentHistory) {
      const k = h.postId + ':' + h.sentAt;
      if (!seenH.has(k)) { seenH.add(k); combined.push(h); }
    }
    nextObj.sentHistory = combined.slice(-80);
  }
  full.instagram = nextObj;
  fs.mkdirSync(path.dirname(GROWTH_PATH), { recursive: true });
  const tmp = GROWTH_PATH + '.tmp.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
  fs.writeFileSync(tmp, JSON.stringify(full, null, 2), 'utf8');
  fs.renameSync(tmp, GROWTH_PATH);
  return nextObj;
};
const picked = $('İçerik Seç & Tekrar Kontrolü').first().json;
const published = $input.first()?.json || {};
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (!Array.isArray(sd.sentHistory)) sd.sentHistory = [];
if (!sd.sentIds.includes(picked.postId)) sd.sentIds.push(picked.postId);
const nowSec = Math.floor(Date.now() / 1000);
const todayTrt = new Date((nowSec + 3 * 3600) * 1000).toISOString().slice(0, 10);
const prevSdCount = sd.dayTrt === todayTrt ? Number(sd.countToday || 0) : 0;
sd.lastPublishedAt = nowSec;
sd.sentHistory.push({
  postId: picked.postId,
  mediaType: picked.mediaType,
  igMediaId: String(published.id || ''),
  sentAt: sd.lastPublishedAt
});
sd.sentHistory = sd.sentHistory.slice(-50);
const synced = syncDiskPlatform({
  sentIds: sd.sentIds,
  lastPublishedAt: sd.lastPublishedAt,
  dayTrt: todayTrt,
  prevSdCount,
  sentHistory: sd.sentHistory
}, true);
sd.sentIds = synced.sentIds;
sd.lastPublishedAt = synced.lastPublishedAt;
sd.dayTrt = synced.dayTrt;
sd.countToday = synced.countToday;
return [{ json: { ok: true, postId: picked.postId, mediaType: picked.mediaType, igMediaId: published.id || null, username: picked.username, countToday: sd.countToday } }];

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const readDiskPlatform = () => {
  try {
    const fs = require('fs');
    if (!fs.existsSync(GROWTH_PATH)) return {};
    const full = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8'));
    return (full && typeof full.instagram === 'object' && full.instagram) ? full.instagram : {};
  } catch { return {}; }
};
const nowSec = Math.floor(Date.now() / 1000);
const trt = new Date((nowSec + 3 * 3600) * 1000);
const today = trt.toISOString().slice(0, 10);
const h = trt.getUTCHours();
const m = trt.getUTCMinutes();
const hash = (s) => { let v = 2166136261; for (let i = 0; i < s.length; i++) v = Math.imul(v ^ s.charCodeAt(i), 16777619) >>> 0; return v; };
const h1 = hash(today + ':ig_slot1');
const h2 = hash(today + ':ig_slot2');
const t1H = 15 + (h1 % 2);
const t1M = 4 + ((h1 >>> 4) % 49);
const t2H = 20 + (h2 % 3);
const t2M = 4 + ((h2 >>> 4) % 49);
const sd = $getWorkflowStaticData('global');
const diskIg = readDiskPlatform();
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (Array.isArray(diskIg.sentIds)) sd.sentIds = [...new Set([...sd.sentIds, ...diskIg.sentIds])];
sd.lastPublishedAt = Math.max(Number(sd.lastPublishedAt || 0), Number(diskIg.lastPublishedAt || 0));
const sdCount = sd.dayTrt === today ? Number(sd.countToday || 0) : 0;
const diskCount = diskIg.dayTrt === today ? Number(diskIg.countToday || 0) : 0;
sd.dayTrt = today;
sd.countToday = Math.max(sdCount, diskCount);
if (sd.countToday >= 2) return [];
const lastPub = Number(sd.lastPublishedAt || 0);
if (lastPub && (nowSec - lastPub < 5 * 3600)) return [];
const inSlot1 = (h > t1H || (h === t1H && m >= t1M)) && h <= 18;
const inSlot2 = (h > t2H || (h === t2H && m >= t2M)) && h <= 23;
if (!inSlot1 && !inSlot2) return [];
return [{ json: { ok: true, slot: inSlot2 ? 2 : 1, target1: t1H + ':' + String(t1M).padStart(2, '0'), target2: t2H + ':' + String(t2M).padStart(2, '0') } }];
